<script>
import processBar from "../../components/public/processBar.vue"
// 红色
const red = '#d9001b'
// 蓝色
const blue = '#02a7f0'
// 默认灰色
const dc = '#bfc4cb'

export default {
    components: {
        processBar
    },
    props: {
        pelvicRisk: Object
    },
    data() {
        return {
            isDeviceReport: window.sessionStorage.getItem('isDeviceReport'),
            tabinx: 0,
            // 等级色值
            colorLevels: ["#51ED97", "#EAB04D", "#FD3741"],
            // 等级
            0: 0,
            preScore: 0, // 当前状态评分
            preStatus: 0, // 当前状态值
            pelvicDes: "", // 风险结论
            pelvicDesArry: ["前倾风险高", "后倾风险高", "旋转风险高"],
            muscleAssessment: ["髂腰肌/竖脊肌下部紧张 、腹横肌薄弱", "股后肌群、臀肌、竖脊肌紧张、髂腰肌弱", "单侧臀中肌薄弱 / 腰方肌不平衡"],
            muscleDesArray: [],
            interval: [0, 30, 50],
            dataArray: { LRMuscle: dc, RRMuscle: dc, LeftButtock: dc, rightButtock: dc, LeftBuL: dc, rightBuR: dc }
        }
    },
    created() {
        this.init()
    },
    methods: {
        init() {
            this.tabinx = 0
            this.preScore = Math.round(this.pelvicRisk.pelvicTiltScore)
            this.preStatus = this.pelvicRisk.pelvicTiltStatus
            let descriptions = []
            if (this.preStatus) {
                descriptions.push(this.pelvicDesArry[0])
                this.muscleDesArray.push(this.muscleAssessment[0])
            }
            if (this.pelvicRisk.retroversionStatus) {
                descriptions.push(this.pelvicDesArry[1])
                this.muscleDesArray.push(this.muscleAssessment[1])
            }
            if (this.pelvicRisk.rotationStatus) {
                descriptions.push(this.pelvicDesArry[2])
                this.muscleDesArray.push(this.muscleAssessment[2])
            }
            if (descriptions.length > 0) {
                this.pelvicDes = descriptions.join("、")
            } else {
                this.muscleDesArray.push('骨盆相关肌肉评估正常，请继续保持良好的生活习惯。')
                this.pelvicDes = "以上项目均正常"
            }

            // 骨盆前倾
            if (this.pelvicRisk.pelvicTiltStatus) {
                this.dataArray.LRMuscle = red
                this.dataArray.RRMuscle = red
                this.dataArray.LeftButtock = blue
                this.dataArray.rightButtock = blue
            } else if (this.pelvicRisk.retroversionStatus) {
                this.dataArray.LRMuscle = blue
                this.dataArray.RRMuscle = blue
                this.dataArray.LeftButtock = red
                this.dataArray.rightButtock = red
            }
            // else if (this.pelvicRisk.rotationStatus) {

            // }
        },
        onChange(index) {
            this.tabinx = index
            switch (index) {
                case 0:
                    this.preScore = Math.round(this.pelvicRisk.pelvicTiltScore)
                    this.preStatus = this.pelvicRisk.pelvicTiltStatus
                    this.interval = [0, 30, 50]
                    break
                case 1:
                    this.preScore = Math.round(this.pelvicRisk.retroversionScore)
                    this.preStatus = this.pelvicRisk.retroversionStatus
                    this.interval = [0, 30, 50]
                    break
                case 2:
                    this.preScore = Math.round(this.pelvicRisk.rotationScore)
                    this.preStatus = this.pelvicRisk.rotationStatus
                    this.interval = [0, 25, 40]
                    break
            }
        },
    }
}
</script>

